type PromoteLibraryQueueParams struct {
	ID     pgtype.UUID
	Now    pgtype.Timestamptz
	ItemID pgtype.UUID
}

// Sıradaki kişiye ödünç isteği açar (kalemin etkin ödüncü yokken):
// sıranın başı silinir, geri çekilmemiş kalem için `requested` ödünç
// yazılır. Kimse yoksa satır dönmez.
func (q *Queries) PromoteLibraryQueue(ctx context.Context, arg PromoteLibraryQueueParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, promoteLibraryQueue, arg.ID, arg.Now, arg.ItemID)
	var borrower_id pgtype.UUID
	err := row.Scan(&borrower_id)
	return borrower_id, err
}

